// ─── VIGNETTE SPOTLIGHT CURSOR ──────────────────────────────
// Soft marigold-tinted glow follows the mouse — barely visible, just a feeling.
// On interactive elements, a small marigold dot appears for precision feedback.
(function setupVignette() {
  if (window.matchMedia('(max-width: 768px)').matches) return;
  const root = document.documentElement;
  const hotDot = document.getElementById('hot-dot');
  let mx = window.innerWidth / 2, my = window.innerHeight / 2;
  let dx = mx, dy = my;

  document.addEventListener('mousemove', (e) => {
    mx = e.clientX; my = e.clientY;
    if (hotDot) {
      hotDot.style.left = mx + 'px';
      hotDot.style.top = my + 'px';
    }
  });

  function tick() {
    dx += (mx - dx) * 0.16;
    dy += (my - dy) * 0.16;
    root.style.setProperty('--mx', dx + 'px');
    root.style.setProperty('--my', dy + 'px');
    requestAnimationFrame(tick);
  }
  tick();

  const interactiveSel = '[data-cursor], button, a, input, textarea, .film-card, summary, details';
  document.querySelectorAll(interactiveSel).forEach(el => {
    el.addEventListener('mouseenter', () => hotDot && hotDot.classList.add('active'));
    el.addEventListener('mouseleave', () => hotDot && hotDot.classList.remove('active'));
  });
})();

// ─── HERO VIDEO PLAY GUARANTEE ──────────────────────────────
// Some browsers (Safari, low-power mode) block autoplay even with muted+playsinline.
// We attempt to play explicitly, retry on errors, and fall back to user-initiated start.
(function ensureHeroPlay() {
  const video = document.querySelector('.hero-video');
  if (!video) return;

  function tryPlay() {
    const p = video.play();
    if (p && typeof p.then === 'function') {
      p.catch(() => {
        // Autoplay blocked — wait for first user gesture, then try again
        const onGesture = () => {
          video.play().catch(() => {});
          document.removeEventListener('click', onGesture);
          document.removeEventListener('scroll', onGesture);
          document.removeEventListener('touchstart', onGesture);
        };
        document.addEventListener('click', onGesture, { once: true });
        document.addEventListener('scroll', onGesture, { once: true });
        document.addEventListener('touchstart', onGesture, { once: true });
      });
    }
  }

  // Try immediately when metadata loads, and again on full load
  if (video.readyState >= 2) tryPlay();
  video.addEventListener('loadedmetadata', tryPlay);
  video.addEventListener('canplay', tryPlay);
  // Resume on visibility return
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden && video.paused) tryPlay();
  });
})();

// ─── MOBILE MENU ────────────────────────────────────────────
(function setupMobileMenu() {
  const toggle = document.getElementById('nav-toggle');
  const overlay = document.getElementById('menu-overlay');
  const closeBtn = document.getElementById('menu-close');
  if (!toggle || !overlay) return;

  function open() {
    overlay.classList.add('open');
    overlay.setAttribute('aria-hidden', 'false');
    toggle.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
  }
  function close() {
    overlay.classList.remove('open');
    overlay.setAttribute('aria-hidden', 'true');
    toggle.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  }
  toggle.addEventListener('click', open);
  if (closeBtn) closeBtn.addEventListener('click', close);
  // Close on link click (so anchor navigation works)
  overlay.querySelectorAll('a').forEach(a => a.addEventListener('click', close));
  // Close on Escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && overlay.classList.contains('open')) close();
  });
})();

// ─── REVEAL ON SCROLL ───────────────────────────────────────
// Sections fade in as they enter the viewport. Includes a safety net:
// after 2.5s, any section that hasn't been revealed gets revealed anyway,
// so content can never be permanently invisible if the observer misfires.
(function setupReveal() {
  const items = document.querySelectorAll('.reveal');
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        e.target.classList.add('in');
        observer.unobserve(e.target);
      }
    });
  }, { threshold: 0.05, rootMargin: '0px 0px -50px 0px' });
  items.forEach(el => observer.observe(el));

  // Safety: force-reveal any laggards after 2.5 seconds — better visible
  // than invisible if Safari/low-power mode skips animations.
  setTimeout(() => {
    document.querySelectorAll('.reveal:not(.in)').forEach(el => el.classList.add('in'));
  }, 2500);
})();

// ─── VIDEO MODAL (for film grid clicks) ─────────────────────
const modal = document.getElementById('modal');
const iframe = document.getElementById('modal-iframe');
function openVideo(id) {
  iframe.src = `https://www.youtube.com/embed/${id}?autoplay=1&rel=0&modestbranding=1`;
  modal.classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeVideo() {
  modal.classList.remove('open');
  iframe.src = '';
  document.body.style.overflow = '';
}
document.querySelectorAll('[data-yt]').forEach(el => {
  el.addEventListener('click', () => openVideo(el.getAttribute('data-yt')));
});
document.querySelector('.modal-close').addEventListener('click', closeVideo);
modal.addEventListener('click', (e) => { if (e.target === modal) closeVideo(); });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeVideo(); });

// ─── PRE-AI SHOWREEL — CLICK TO PLAY ────────────────────────
// Replaces the poster image with the YouTube iframe only when user clicks.
// Avoids autoplay restrictions, Error 153, and cuts initial page weight.
(function setupOriginVideo() {
  const wrap = document.getElementById('origin-video');
  if (!wrap) return;
  const playBtn = wrap.querySelector('.origin-play');
  const poster = wrap.querySelector('.origin-poster');
  function play() {
    const iframe = document.createElement('iframe');
    iframe.src = 'https://www.youtube.com/embed/F-spjRJSgus?autoplay=1&rel=0&modestbranding=1';
    iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
    iframe.allowFullscreen = true;
    iframe.frameBorder = '0';
    wrap.appendChild(iframe);
    if (poster) poster.style.display = 'none';
    if (playBtn) playBtn.style.display = 'none';
  }
  wrap.addEventListener('click', play);
})();

// ─── SHOWCASE FILM — CLICK TO PLAY ──────────────────────────
// Hero piece. Same pattern as Pre-AI Showreel but uses data-yt-id so the
// embed video can be swapped without touching JS.
(function setupShowcaseVideo() {
  const SVG_FS_ON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>';
  const SVG_FS_OFF = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5"/></svg>';
  const SVG_MUTE = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5 6 9H3v6h3l5 4V5z"/><line x1="22" y1="9" x2="16" y2="15"/><line x1="16" y1="9" x2="22" y2="15"/></svg>';
  const SVG_SOUND = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5 6 9H3v6h3l5 4V5z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/></svg>';
  document.querySelectorAll('.showcase-player[data-yt-id]').forEach(wrap => {
    const ytId = wrap.dataset.ytId;
    if (!ytId) return;
    const poster = wrap.querySelector('.showcase-poster');
    const playWrap = wrap.querySelector('.showcase-play-wrap');
    const caption = wrap.querySelector('.showcase-caption');
    let iframe = null, muted = true;
    const ctrls = document.createElement('div');
    ctrls.className = 'sc-ctrls';
    ctrls.innerHTML = '<button class="sc-btn" data-sc="audio" aria-label="Toggle sound">' + SVG_MUTE + '</button>' +
                      '<button class="sc-btn" data-sc="fs" aria-label="Toggle fullscreen">' + SVG_FS_ON + '</button>';
    wrap.appendChild(ctrls);
    const audioBtn = ctrls.querySelector('[data-sc="audio"]');
    const fsBtn = ctrls.querySelector('[data-sc="fs"]');
    function cmd(func) {
      if (!iframe) return;
      iframe.contentWindow.postMessage(JSON.stringify({ event: 'command', func, args: [] }), '*');
    }
    function ensureIframe() {
      if (iframe) return;
      iframe = document.createElement('iframe');
      const org = location.protocol.indexOf('http') === 0 ? '&origin=' + encodeURIComponent(location.origin) : '';
      iframe.src = 'https://www.youtube-nocookie.com/embed/' + ytId + '?autoplay=1&mute=1&playsinline=1&rel=0&loop=1&playlist=' + ytId + '&enablejsapi=1' + org;
      iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share; fullscreen';
      iframe.allowFullscreen = true;
      iframe.frameBorder = '0';
      iframe.addEventListener('load', () => setTimeout(() => { cmd('playVideo'); cmd(muted ? 'mute' : 'unMute'); }, 450));
      wrap.insertBefore(iframe, ctrls);
      setTimeout(() => {
        if (poster) poster.style.opacity = '0';
        if (playWrap) playWrap.style.display = 'none';
        if (caption) caption.style.opacity = '0';
      }, 900);
    }
    function setMuted(m) {
      muted = m;
      cmd(m ? 'mute' : 'unMute');
      audioBtn.innerHTML = m ? SVG_MUTE : SVG_SOUND;
    }
    /* auto play (muted) when scrolled into view; pause when away */
    const io = new IntersectionObserver(es => es.forEach(e => {
      if (e.isIntersecting) { ensureIframe(); cmd('playVideo'); }
      else cmd('pauseVideo');
    }), { threshold: 0.35 });
    io.observe(wrap);
    audioBtn.addEventListener('click', e => { e.stopPropagation(); ensureIframe(); setMuted(!muted); cmd('playVideo'); });
    fsBtn.addEventListener('click', e => {
      e.stopPropagation();
      if (document.fullscreenElement) document.exitFullscreen();
      else { ensureIframe(); wrap.requestFullscreen && wrap.requestFullscreen(); setMuted(false); cmd('playVideo'); }
    });
    wrap.addEventListener('click', e => {
      if (e.target.closest('.sc-btn')) return;
      ensureIframe();
      if (!document.fullscreenElement) { wrap.requestFullscreen && wrap.requestFullscreen(); setMuted(false); }
      cmd('playVideo');
    });
    document.addEventListener('fullscreenchange', () => {
      fsBtn.innerHTML = document.fullscreenElement === wrap ? SVG_FS_OFF : SVG_FS_ON;
    });
  });
})();

// ─── CONTACT FORM ───────────────────────────────────────────
// Submits via Formspree (if FORMSPREE_ID is set in window) — otherwise opens
// the user's mail client with the inquiry pre-filled. Shows success/error states.
(function setupContactForm() {
  const form = document.getElementById('contact-form');
  if (!form) return;
  const status = document.getElementById('form-status');
  const button = document.getElementById('contact-submit');

  function setStatus(msg, kind) {
    if (!status) return;
    status.textContent = msg;
    status.className = 'form-status ' + (kind || '');
  }

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const data = {
      name:    form.querySelector('#name').value.trim(),
      email:   form.querySelector('#email').value.trim(),
      company: form.querySelector('#company').value.trim(),
      inquiry: form.querySelector('#inquiry').value.trim(),
    };

    if (!data.name || !data.email || !data.inquiry) {
      setStatus('Please fill in name, email, and your inquiry.', 'error');
      return;
    }

    button.disabled = true;
    const originalText = button.textContent;
    button.textContent = 'Sending...';
    setStatus('', '');

    // Try Formspree if configured
    const FORMSPREE_ID = window.FORMSPREE_ID || '';
    if (FORMSPREE_ID) {
      try {
        const res = await fetch(`https://formspree.io/f/${FORMSPREE_ID}`, {
          method: 'POST',
          headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name: data.name,
            email: data.email,
            company: data.company || '—',
            message: data.inquiry,
            _subject: `Inquiry from ${data.name}${data.company ? ' / ' + data.company : ''}`
          })
        });
        if (res.ok) {
          form.reset();
          setStatus('Thank you. Your inquiry is in. We\'ll be in touch shortly.', 'success');
          button.textContent = 'Sent ✓';
          setTimeout(() => { button.textContent = originalText; button.disabled = false; }, 4000);
          return;
        }
        throw new Error('Form submission failed');
      } catch (err) {
        // Fall through to mailto
      }
    }

    // Fallback: open mail client with body pre-filled
    const subject = encodeURIComponent(`Inquiry from ${data.name}${data.company ? ' / ' + data.company : ''}`);
    const body = encodeURIComponent(
      `Name: ${data.name}\n` +
      `Email: ${data.email}\n` +
      `Company: ${data.company || '—'}\n\n` +
      data.inquiry
    );
    window.location.href = `mailto:chntan.n.shah@gmail.com?subject=${subject}&body=${body}`;
    setStatus('Opening your mail client. If nothing happens, please email chntan.n.shah@gmail.com directly.', 'info');
    button.disabled = false;
    button.textContent = originalText;
  });
})();

/* ─── SLIT HERO WORD ROTATOR ───────────────────────────── */
(function () {
  const rot = document.getElementById('hs-rotator');
  if (!rot) return;
  const slit = rot.parentElement;
  const words = [...rot.querySelectorAll('.hs-word')];
  words.forEach(w => w.classList.remove('is-on', 'is-off'));
  /* build vertical reel: words stacked + clone of first for seamless loop */
  const reel = document.createElement('div');
  reel.className = 'hs-reel';
  words.forEach(w => reel.appendChild(w));
  reel.appendChild(words[0].cloneNode(true));
  rot.innerHTML = ''; rot.appendChild(reel);
  rot.style.height = '100%';
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  let pos = 0, Hh = slit.clientHeight;
  addEventListener('resize', () => {
    Hh = slit.clientHeight;
    reel.style.transition = 'none';
    reel.style.transform = 'translateY(' + (-pos * Hh) + 'px)';
  });
  const EASE = 'cubic-bezier(0.85, 0, 0.1, 1)'; /* fast pull, hard mechanical stick */
  setInterval(() => {
    pos++;
    reel.style.transition = 'transform 0.5s ' + EASE;
    reel.style.transform = 'translateY(' + (-pos * Hh) + 'px)';
  }, 2400);
  reel.addEventListener('transitionend', () => {
    if (pos >= words.length) {
      pos = 0;
      reel.style.transition = 'none';
      reel.style.transform = 'translateY(0)';
    }
  });
})();
var WH_SW=160, WH_SH=90;
var WH_SCENES=['','','','',''];

/* ─── CODE-WORLD INTRO v14 — black & white WebGL build, original for Woo Hoo Media Labs.
   An AI engine made of code, rendering worlds: infinity loop of glyphs →
   scenes from the studio's own films drawn entirely in code characters →
   scroll zooms through world after world, looping → click: the code falls
   → the site appears. ─── */
function WH_BOOT() {
  const intro = document.getElementById('px-intro');
  if (!intro) return;
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduced || !window.THREE) { intro.remove(); return; }

  const cvEl = document.getElementById('px-canvas');
  let renderer;
  try {
    renderer = new THREE.WebGLRenderer({ canvas: cvEl, antialias: false, alpha: false, powerPreference: 'high-performance' });
  } catch (e) { intro.remove(); return; }

  let W = intro.clientWidth, H = intro.clientHeight;
  const DPR = Math.min(1.75, window.devicePixelRatio || 1);
  renderer.setPixelRatio(DPR);
  renderer.setSize(W, H, false);
  renderer.setClearColor(0x050505, 1);

  const scene3 = new THREE.Scene();
  const FOV = 50;
  let camDist = (H / 2) / Math.tan((FOV / 2) * Math.PI / 180);
  const camera = new THREE.PerspectiveCamera(FOV, W / H, 1, camDist * 8);
  camera.position.z = camDist;

  document.body.classList.add('intro-lock');

  /* B&W code glyph atlas — index 0..15 = brightness level, denser = brighter */
  const LV = [' ', '.', ':', ';', '+', '<', '>', '(', ')', '{', '}', '0', '1', '8', '#', '█'];
  const atlas = document.createElement('canvas');
  atlas.width = atlas.height = 1024;
  const ac = atlas.getContext('2d');
  ac.fillStyle = '#fff'; ac.textAlign = 'center'; ac.textBaseline = 'middle';
  ac.font = '600 195px "Space Grotesk", "Courier New", monospace';
  LV.forEach((g, i) => { if (i > 0) ac.fillText(g, (i % 4) * 256 + 128, Math.floor(i / 4) * 256 + 142); });
  const tex = new THREE.CanvasTexture(atlas);

  const NPTS = WH_SW * WH_SH; // 9216
  const cell = () => Math.min(W / WH_SW, H / WH_SH);

  function makeCloud() {
    const pos = new Float32Array(NPTS * 3);
    const alpha = new Float32Array(NPTS);
    const glyph = new Float32Array(NPTS);
    const base = new Float32Array(NPTS);       // scene brightness 0..15
    const jz = new Float32Array(NPTS);
    for (let i = 0; i < NPTS; i++) jz[i] = (Math.random() - 0.5) * 18;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
    geo.setAttribute('aGlyph', new THREE.BufferAttribute(glyph, 1));
    const mat = new THREE.ShaderMaterial({
      uniforms: { uTex: { value: tex }, uScale: { value: H * DPR / 2 }, uSize: { value: cell() * 2.05 }, uFade: { value: 1 } },
      vertexShader: [
        'attribute float aAlpha; attribute float aGlyph;',
        'varying float vAlpha; varying float vGlyph;',
        'uniform float uScale; uniform float uSize;',
        'void main(){',
        '  vAlpha=aAlpha; vGlyph=aGlyph;',
        '  vec4 mv=modelViewMatrix*vec4(position,1.0);',
        '  gl_PointSize=uSize*uScale/(-mv.z);',
        '  gl_Position=projectionMatrix*mv;',
        '}'].join('\n'),
      fragmentShader: [
        'uniform sampler2D uTex; uniform float uFade;',
        'varying float vAlpha; varying float vGlyph;',
        'void main(){',
        '  float col=mod(vGlyph,4.0); float row=floor(vGlyph/4.0);',
        '  vec2 uv=vec2((col+gl_PointCoord.x)*0.25, 1.0-(row+gl_PointCoord.y)*0.25);',
        '  vec4 t=texture2D(uTex,uv);',
        '  float a=t.a*vAlpha*uFade;',
        '  if(a<0.02) discard;',
        '  gl_FragColor=vec4(vec3(0.93),a);',
        '}'].join('\n'),
      transparent: true, depthWrite: false
    });
    const pts = new THREE.Points(geo, mat);
    scene3.add(pts);
    return { geo, mat, pts, pos, alpha, glyph, base, jz, vel: null };
  }

  const A = makeCloud(), B = makeCloud();

  function latticeXY(i) {
    const c = cell();
    const x = (i % WH_SW - (WH_SW - 1) / 2) * c;
    const y = -((i / WH_SW | 0) - (WH_SH - 1) / 2) * c;
    return [x, y];
  }
  function loadScene(cloud, idx) {
    const s = WH_SCENES[idx % WH_SCENES.length];
    for (let i = 0; i < NPTS; i++) {
      const v = parseInt(s[i], 16);
      cloud.base[i] = v;
      cloud.glyph[i] = v;
      const [x, y] = latticeXY(i);
      cloud.pos[i * 3] = x; cloud.pos[i * 3 + 1] = y; cloud.pos[i * 3 + 2] = cloud.jz[i];
    }
    cloud.geo.attributes.aGlyph.needsUpdate = true;
    cloud.geo.attributes.position.needsUpdate = true;
  }

  /* ── state ── */
  let mode = 'scenes', t0 = performance.now(), dead = false;
  let depth = 0, sceneIdx = 0, morphStart = 0;
  const infFrom = new Float32Array(NPTS * 3);
  const hint = document.getElementById('px-hint');
  const eo = p => 1 - Math.pow(1 - p, 3);
  const sm = (a, b, x) => { const t = Math.max(0, Math.min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); };

  /* init: cloud A scattered for infinity, B hidden */
  for (let i = 0; i < NPTS; i++) {
    A.pos[i * 3] = (Math.random() - 0.5) * W * 1.5;
    A.pos[i * 3 + 1] = (Math.random() - 0.5) * H * 1.5;
    A.pos[i * 3 + 2] = (Math.random() - 0.5) * 300;
    A.glyph[i] = Math.random() < 0.55 ? (Math.random() < 0.5 ? 11 : 12) : 4 + ((Math.random() * 11) | 0);
    A.alpha[i] = 0;
    B.alpha[i] = 0;
  }
  A.geo.attributes.aGlyph.needsUpdate = true;
  loadScene(A, 0); loadScene(B, 1);

  function startMorphToScenes() {
    if (mode !== 'inf') return;
    infFrom.set(A.pos);
    loadScene(B, 1);            // pre-stage next world
    B.mat.uniforms.uFade.value = 0;
    /* targets for A = scene 0 lattice; positions currently on infinity */
    const s = WH_SCENES[0];
    for (let i = 0; i < NPTS; i++) { A.base[i] = parseInt(s[i], 16); A.glyph[i] = A.base[i]; }
    A.geo.attributes.aGlyph.needsUpdate = true;
    mode = 'toScene'; morphStart = performance.now();
    hint.textContent = 'Scroll to travel · Click to enter';
  }

  function fallSFX() {
    try {
      const A = new (window.AudioContext || window.webkitAudioContext)();
      const g = A.createGain(); g.gain.value = 0.16; g.connect(A.destination);
      for (let i = 0; i < 52; i++) {
        const t = A.currentTime + Math.random() * 1.15;
        const o = A.createOscillator(); o.type = 'square';
        const f = 1300 + Math.random() * 2900;
        o.frequency.setValueAtTime(f, t);
        o.frequency.exponentialRampToValueAtTime(f * 0.35, t + 0.1);
        const e = A.createGain();
        e.gain.setValueAtTime(0.0001, t);
        e.gain.exponentialRampToValueAtTime(0.35 + Math.random() * 0.4, t + 0.006);
        e.gain.exponentialRampToValueAtTime(0.0001, t + 0.09 + Math.random() * 0.09);
        o.connect(e); e.connect(g); o.start(t); o.stop(t + 0.22);
      }
      const dur = 1.25, buf = A.createBuffer(1, A.sampleRate * dur, A.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 2.2) * 0.22;
      const s = A.createBufferSource(); s.buffer = buf;
      const hp = A.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 2400;
      s.connect(hp); hp.connect(g); s.start();
    } catch (e) {}
  }
  function beginFall() {
    if (mode === 'fall' || dead) return;
    fallSFX();
    mode = 'fall'; morphStart = performance.now();
    [A, B].forEach(c => {
      c.vel = new Float32Array(NPTS * 2);
      for (let i = 0; i < NPTS; i++) {
        c.vel[i * 2] = (Math.random() - 0.5) * 3;
        c.vel[i * 2 + 1] = Math.random() * 3;
      }
    });
    hint.classList.add('off');
  }
  function finish() {
    if (dead) return; dead = true;
    document.body.classList.remove('intro-lock');
    intro.classList.add('gone');
    setTimeout(() => {
      [A, B].forEach(c => { c.geo.dispose(); c.mat.dispose(); });
      tex.dispose(); renderer.dispose(); intro.remove();
    }, 950);
  }

  /* input */
  let px = 0, py = 0, lastTouchY = null;
  addEventListener('pointermove', e => { px = e.clientX / W - 0.5; py = e.clientY / H - 0.5; });
  intro.addEventListener('wheel', e => {
    e.preventDefault();
    if (mode === 'inf') { startMorphToScenes(); return; }
    if (mode === 'scenes') depth += Math.max(-40, Math.min(40, e.deltaY)) * 0.0011;
  }, { passive: false });
  intro.addEventListener('touchstart', e => { lastTouchY = e.touches[0].clientY; }, { passive: true });
  intro.addEventListener('touchmove', e => {
    e.preventDefault();
    const y = e.touches[0].clientY;
    if (lastTouchY != null) {
      if (mode === 'inf') startMorphToScenes();
      else if (mode === 'scenes') depth += (lastTouchY - y) * 0.0035;
    }
    lastTouchY = y;
  }, { passive: false });
  intro.addEventListener('pointerdown', e => {
    if (e.target.id === 'px-skip') return;
    if (mode === 'inf') { startMorphToScenes(); setTimeout(beginFall, 1400); }
    else beginFall();
  });
  document.getElementById('px-skip').addEventListener('click', finish);

  /* glyph shimmer — codes feel alive */
  setInterval(() => {
    if (dead || (mode !== 'scenes' && mode !== 'toScene')) return;
    [A, B].forEach(c => {
      for (let k = 0; k < (NPTS * 0.03 | 0); k++) {
        const i = (Math.random() * NPTS) | 0;
        const b = c.base[i];
        if (b < 1) continue;
        c.glyph[i] = Math.max(1, Math.min(15, b + ((Math.random() * 3) | 0) - 1));
      }
      c.geo.attributes.aGlyph.needsUpdate = true;
    });
  }, 85);

  let prev = performance.now();
  function frame(now) {
    if (dead) return;
    const dt = Math.min(0.05, (now - prev) / 1000); prev = now;
    const t = (now - t0) / 1000;

    if (mode === 'inf') {
      const a = Math.min(W, H) * 0.36;
      for (let i = 0; i < NPTS; i++) {
        const th = (i / NPTS) * Math.PI * 2 + t * 0.45;
        const s2 = Math.sin(th), den = 1 + s2 * s2;
        const tx = a * Math.cos(th) / den;
        const ty = a * s2 * Math.cos(th) / den;
        const tz = Math.sin(th * 2 + t * 0.8) * 80;
        A.pos[i * 3] += (tx - A.pos[i * 3]) * 0.07;
        A.pos[i * 3 + 1] += (ty - A.pos[i * 3 + 1]) * 0.07;
        A.pos[i * 3 + 2] += (tz - A.pos[i * 3 + 2]) * 0.07;
        A.alpha[i] = 0.34 + 0.4 * (0.5 + 0.5 * Math.sin(t * 2.4 + i * 0.6));
      }
      A.geo.attributes.position.needsUpdate = true;
      A.geo.attributes.aAlpha.needsUpdate = true;
      if (t > 3.6) startMorphToScenes();
    }

    else if (mode === 'toScene') {
      const pr = Math.min(1, (now - morphStart) / 1150);
      for (let i = 0; i < NPTS; i++) {
        const dl = (i % 97) / 97 * 0.25;
        const e = eo(Math.max(0, Math.min(1, (pr - dl) / (1 - dl))));
        const [lx, ly] = latticeXY(i);
        A.pos[i * 3] = infFrom[i * 3] + (lx - infFrom[i * 3]) * e;
        A.pos[i * 3 + 1] = infFrom[i * 3 + 1] + (ly - infFrom[i * 3 + 1]) * e;
        A.pos[i * 3 + 2] = infFrom[i * 3 + 2] + (A.jz[i] - infFrom[i * 3 + 2]) * e;
        A.alpha[i] = (A.base[i] ? 0.28 + 0.72 * A.base[i] / 15 : 0) * (0.3 + 0.7 * e);
      }
      A.geo.attributes.position.needsUpdate = true;
      A.geo.attributes.aAlpha.needsUpdate = true;
      if (pr >= 1) { mode = 'scenes'; depth = 0; }
    }

    else if (mode === 'scenes') {
      depth += dt * 0.085;
      if (depth < 0) depth = 0;
      const newIdx = depth | 0;
      if (newIdx !== sceneIdx) {
        sceneIdx = newIdx;
        /* A becomes the world we just zoomed into (old B); stage the next into the other */
        loadScene(A, sceneIdx);
        loadScene(B, sceneIdx + 1);
      }
      const p = depth - sceneIdx;
      const zA = p * camDist * 0.85;
      const zB = -camDist * 0.9 * (1 - p);
      const boot = Math.min(1, (now - t0) / 700);
      const fA = (1 - sm(0.55, 0.97, p)) * boot;
      const fB = sm(0.12, 0.6, p) * boot;
      A.pts.position.z = zA; B.pts.position.z = zB;
      A.mat.uniforms.uFade.value = fA;
      B.mat.uniforms.uFade.value = fB;
      for (let i = 0; i < NPTS; i++) {
        A.alpha[i] = A.base[i] ? 0.28 + 0.72 * A.base[i] / 15 : 0;
        B.alpha[i] = B.base[i] ? 0.28 + 0.72 * B.base[i] / 15 : 0;
      }
      A.geo.attributes.aAlpha.needsUpdate = true;
      B.geo.attributes.aAlpha.needsUpdate = true;
    }

    else if (mode === 'fall') {
      const pr = Math.min(1, (now - morphStart) / 1100);
      [A, B].forEach(c => {
        if (!c.vel) return;
        for (let i = 0; i < NPTS; i++) {
          c.vel[i * 2 + 1] += 0.55;
          c.pos[i * 3] += c.vel[i * 2];
          c.pos[i * 3 + 1] -= c.vel[i * 2 + 1];
        }
        c.geo.attributes.position.needsUpdate = true;
        c.mat.uniforms.uFade.value *= (1 - pr * 0.06);
      });
      if (pr >= 1) { finish(); return; }
    }

    camera.position.x += (px * 36 - camera.position.x) * 0.05;
    camera.position.y += (-py * 36 - camera.position.y) * 0.05;
    camera.lookAt(0, 0, 0);
    renderer.render(scene3, camera);
    requestAnimationFrame(frame);
  }

  addEventListener('resize', () => {
    W = intro.clientWidth; H = intro.clientHeight;
    renderer.setSize(W, H, false);
    camera.aspect = W / H; camera.updateProjectionMatrix();
    camDist = (H / 2) / Math.tan((FOV / 2) * Math.PI / 180);
    camera.position.z = camDist;
    const sz = cell() * 2.05;
    A.mat.uniforms.uSize.value = sz; B.mat.uniforms.uSize.value = sz;
    A.mat.uniforms.uScale.value = H * DPR / 2; B.mat.uniforms.uScale.value = H * DPR / 2;
  });

  let started = false;
  function startLoop() { if (started || dead) return; started = true; prev = performance.now(); t0 = prev; requestAnimationFrame(frame); }
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(startLoop);
  setTimeout(startLoop, 1000);
}

WH_BOOT();

/* ── Boot Sequence: replay the intro from anywhere ── */
window.WH_REPLAY = function () {
  if (document.getElementById('px-intro')) return;
  document.body.insertAdjacentHTML('afterbegin',
    '<div class="px-intro" id="px-intro" aria-hidden="true">' +
    '<canvas id="px-canvas"></canvas>' +
    '<div class="px-hint" id="px-hint">Scroll to travel \u00b7 Click to enter</div>' +
    '<div class="px-skip" id="px-skip">Skip</div></div>');
  window.scrollTo(0, 0);
  WH_BOOT();
};
document.querySelectorAll('[data-boot]').forEach(el => {
  el.addEventListener('click', e => { e.preventDefault(); window.WH_REPLAY(); });
});
